package Assignments;

public class Operators {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

				
			   
			    int a = 45, b = 3;

			    // addition operator
			    System.out.println("a + b = " + (a + b));

			    // subtraction operator
			    System.out.println("a - b = " + (a - b));

			    // multiplication operator
			    System.out.println("a * b = " + (a * b));

			    // division operator
			    System.out.println("a / b = " + (a / b));

			    // modulo operator
			    System.out.println("a % b = " + (a % b));
			  }
			
	}

